import { z } from 'zod';
import raw from '@data/hydrocarbons_kntt.json';
import {
  loadDataset,
  LocalizedTextSchema,
  ReviewStatusSchema,
  type Source,
} from '@/core/data/dataset';
import { balance, parseEquation } from '../balance';

/**
 * Hóa học 11 KNTT Chương 4 "Hydrocarbon" (Bài 15 Alkane, 16 Hydrocarbon không no, 17 Arene): the
 * homologous series, their members and physical constants as the textbook's tables print them,
 * the shape facts and the book's reactions (data/hydrocarbons_kntt.json, generated by
 * scripts/data/gen_hydrocarbons_kntt.py; review pending, DATA_REVIEW HH11-HC-1). Combustion of any
 * member is balanced from the general formula and checked with the app's exact balancer.
 */
const MemberSchema = z.object({
  class: z.enum(['alkane', 'alkene', 'alkyne', 'arene']),
  name: z.string().min(1),
  formula: z.string().min(1),
  structure: z.string().min(1),
  carbons: z.number().int().positive(),
  mp_C: z.number(),
  bp_C: z.number(),
  density: z.number().positive().nullable(),
  straight: z.boolean(),
  /** False for an arene of the book's table that is not CnH2n−6 (styrene, naphthalene). */
  in_series: z.boolean(),
  page: z.number().int(),
  review_status: ReviewStatusSchema,
});
const Term = z.object({ coef: z.number().int().positive(), formula: z.string() });
const ExtraSchema = z.object({
  classes: z.array(
    z.object({
      id: z.enum(['alkane', 'alkene', 'alkyne', 'arene']),
      name: LocalizedTextSchema,
      a: z.number().int(),
      b: z.number().int(),
      n_min: z.number().int().positive(),
      lesson: z.number().int(),
      page: z.number().int(),
    }),
  ),
  shapes: z.array(z.object({ class: z.string(), text: LocalizedTextSchema, page: z.number() })),
  reactions: z.array(
    z.object({
      class: z.string(),
      kind: LocalizedTextSchema,
      reactants: z.array(Term).min(1),
      products: z.array(Term).min(1),
      conditions: LocalizedTextSchema,
      dH_kJ: z.number().nullable(),
      page: z.number().int(),
    }),
  ),
});

const dataset = loadDataset('hydrocarbons_kntt', MemberSchema, raw);
const extra = ExtraSchema.parse(raw);

export type ClassId = z.infer<typeof MemberSchema>['class'];
export type Member = z.infer<typeof MemberSchema>;
export type HcClass = z.infer<typeof ExtraSchema>['classes'][number];
export type HcReaction = z.infer<typeof ExtraSchema>['reactions'][number];

export const MEMBERS: readonly Member[] = dataset.items;
export const CLASSES: readonly HcClass[] = extra.classes;
export const SHAPES = extra.shapes;
export const HC_REACTIONS: readonly HcReaction[] = extra.reactions;
export const HC_SOURCE: Source = dataset.source;

export const classOf = (id: ClassId): HcClass => {
  const c = CLASSES.find((x) => x.id === id);
  if (!c) throw new Error(`no class ${id}`);
  return c;
};

/** Hydrogens of the n-carbon member: CnH(a·n + b). */
export const hydrogens = (c: HcClass, n: number) => c.a * n + c.b;

/** "C3H8" for the n-carbon member of the series. */
export const formulaOf = (c: HcClass, n: number) =>
  `C${n > 1 ? String(n) : ''}H${String(hydrogens(c, n))}`;

/** Molar mass with the book's atomic masses (C 12, H 1; Bài 12 tr. 72). */
export const molarMass = (c: HcClass, n: number) => 12 * n + hydrogens(c, n);

/**
 * Complete combustion of CnHm (tr. 88, 98): CnHm + (n + m/4) O₂ → n CO₂ + (m/2) H₂O, written with
 * the smallest whole coefficients (×2 when n + m/4 is not whole, as the book's fractions show).
 */
export function combustion(c: HcClass, n: number) {
  const m = hydrogens(c, n);
  const o2x4 = 4 * n + m;
  const k = o2x4 % 4 === 0 ? 1 : o2x4 % 2 === 0 ? 2 : 4;
  return {
    fuel: k,
    o2: (o2x4 * k) / 4,
    co2: n * k,
    h2o: (m * k) / 2,
    formula: formulaOf(c, n),
  };
}

/** Independent check: the app's exact balancer on the same equation. */
export function balancedCombustion(c: HcClass, n: number): number[] | null {
  const r = balance(parseEquation(`${formulaOf(c, n)} + O2 = CO2 + H2O`));
  return r.kind === 'balanced' ? r.coefficients : null;
}
